#nullable enable
using System.Collections.Immutable;
using HourBooking.Contracts;

namespace HourBooking.Slices.Booking;

/// <summary>
/// Live aggregation over the Timesheet stream, keyed by employeeId + month. Nothing registers a
/// projection for this: Marten folds it on demand when the decider asks.
///
/// Folds every event of the stream, not only this slice's, because the one question it answers — is
/// this day+project already taken — can be answered by a booking a person made just as easily as by a
/// zero this automation wrote earlier.
///
/// Near-identical to BookHoursState, and that duplication is the design's known cost rather than an
/// oversight: two slices asking their own questions of one stream produce two folds. Sharing one would
/// couple the slices, so it is reported instead of "fixed".
///
/// No Create method: a no-arg constructor lets any event open the stream. ZeroHoursFilled genuinely
/// can be first — an employee who leaves a project having booked nothing that month opens their own
/// timesheet with a zero. See ANTI-PATTERNS.md #1.
/// </summary>
public sealed record FillZeroHoursState
{
    /// <summary>
    /// terminal="hours:const" on the command: the hours are not carried by the data flow, the handler
    /// supplies them, and the constant is 0. "we fill out the remainder of the month with 0 hours
    /// booked per day."
    /// </summary>
    public const decimal ZeroHours = 0m;

    public string Id { get; init; } = default!;

    /// <summary>Marten's convention. The aggregate workflow uses it for optimistic concurrency.</summary>
    public int Version { get; set; }

    /// <summary>
    /// One line per booking still standing, keyed by bookingId because that is all HoursCorrected and
    /// BookingRemoved carry.
    /// </summary>
    public ImmutableDictionary<Guid, Line> Lines { get; init; } = ImmutableDictionary<Guid, Line>.Empty;

    /// <summary>ZeroFilled records WHICH writer put the line there, so a rejection can say why.</summary>
    public sealed record Line(DateOnly Date, Guid ProjectId, bool ZeroFilled);

    public static string StreamKey(Guid employeeId, string month) => $"timesheet:{employeeId}:{month}";

    // --- what the decider asks it ----------------------------------------------------------------

    /// <summary>
    /// The line standing for this day+project, or null. One query answers both halves of the only rule
    /// this slice enforces on the stream:
    ///
    ///   * a ZeroFilled line is GWT 4 verbatim — "a day already zero-filled is not filled twice".
    ///   * a hand-booked line is the expert's stated invariant, "there may be only one HoursBooked per
    ///     day+project", which the automation is no more entitled to break than a person is. The model
    ///     gives no separate rule name for that case, so it rejects under the one name it does give and
    ///     the difference shows up in the detail text. Flagged as a modelling gap rather than named
    ///     something invented.
    /// </summary>
    public Line? Standing(DateOnly date, Guid projectId) =>
        Lines.Values.FirstOrDefault(l => l.Date == date && l.ProjectId == projectId);

    // --- the fold --------------------------------------------------------------------------------

    public static FillZeroHoursState Apply(HoursBooked e, FillZeroHoursState current) =>
        current with { Lines = current.Lines.SetItem(e.BookingId, new Line(e.Date, e.ProjectId, false)) };

    /// <summary>
    /// A correction changes hours and note only. This slice decides on day+project occupancy, and a
    /// correction moves neither, so the fold is deliberately a no-op — not an unfinished TODO.
    /// </summary>
    public static FillZeroHoursState Apply(HoursCorrected e, FillZeroHoursState current) => current;

    /// <summary>A removed booking frees the day+project again, so a later zero-fill may take it.</summary>
    public static FillZeroHoursState Apply(BookingRemoved e, FillZeroHoursState current) =>
        current with { Lines = current.Lines.Remove(e.BookingId) };

    public static FillZeroHoursState Apply(ZeroHoursFilled e, FillZeroHoursState current) =>
        current with { Lines = current.Lines.SetItem(e.BookingId, new Line(e.Date, e.ProjectId, true)) };
}
